-- Follow-agenda changes also leave the intro; an incoming music cue takes precedence.
CREATE OR REPLACE FUNCTION public.studio_leave_intro_audio() RETURNS trigger
LANGUAGE plpgsql SET search_path=public AS $$
DECLARE d jsonb; previous jsonb; incoming boolean; now_ms bigint;
BEGIN
 IF OLD.mode<>'studio' OR (NEW.mode='studio' AND NEW.frame_id IS NOT DISTINCT FROM OLD.frame_id)
    OR NEW.audio IS DISTINCT FROM OLD.audio OR NEW.audio->>'status'<>'playing' THEN RETURN NEW; END IF;
 SELECT document INTO d FROM studio_state WHERE project_id=NEW.project_id;
 SELECT n INTO previous FROM jsonb_array_elements(d->'nodes') n WHERE n->>'id'=OLD.frame_id::text;
 IF previous IS NULL OR NOT(previous ? 'intro' OR previous#>>'{eventSource,template}'='cover') THEN RETURN NEW; END IF;
 SELECT EXISTS(SELECT 1 FROM jsonb_array_elements(coalesce(d#>'{show,cues}','[]')) c
  JOIN studio_asset a ON a.id=(c->>'assetId')::uuid AND a.project_id=NEW.project_id AND a.ready
   AND a.workspace_id IS NULL AND a.mime_type IN ('audio/mpeg','audio/wav')
  WHERE c->>'frameId'=NEW.frame_id::text AND c->>'trigger' IN ('enter','activate') AND NEW.mode='studio') INTO incoming;
 IF incoming THEN RETURN NEW; END IF;
 now_ms:=(extract(epoch FROM clock_timestamp())*1000)::bigint;
 NEW.audio:=NEW.audio || jsonb_build_object('status','stopped','position',0,'fadeSeconds',1,'at',now_ms);
 RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS studio_leave_intro_audio ON public.event_presentation;
CREATE TRIGGER studio_leave_intro_audio BEFORE UPDATE OF frame_id,mode ON public.event_presentation
FOR EACH ROW EXECUTE FUNCTION public.studio_leave_intro_audio();

-- Add only background settings. Preserve IDs, layout, bindings and every user-created node.
DO $$
DECLARE r record; updated_nodes jsonb;
BEGIN
 FOR r IN SELECT s.project_id,s.document FROM studio_state s JOIN studio_project p ON p.id=s.project_id
  WHERE p.event_id IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(s.document->'nodes') n
   WHERE n->>'type'='frame' AND n#>>'{eventSource,template}'='cover' AND NOT(n ? 'intro'))
 LOOP
  SELECT jsonb_agg(CASE WHEN n->>'type'='frame' AND n#>>'{eventSource,template}'='cover' AND NOT(n ? 'intro')
   THEN n || '{"intro":{"mode":"spatial","assetId":null,"intensity":0.45}}'::jsonb ELSE n END ORDER BY ord)
   INTO updated_nodes FROM jsonb_array_elements(r.document->'nodes') WITH ORDINALITY AS parts(n,ord);
  PERFORM set_config('polity.canvas_command',r.project_id::text,true);
  UPDATE studio_state SET document=jsonb_set(document,'{nodes}',updated_nodes),content_revision=content_revision+1,
   updated_at=(extract(epoch FROM clock_timestamp())*1000)::bigint WHERE project_id=r.project_id;
 END LOOP;
 PERFORM set_config('polity.canvas_command','',true);
END;
$$;
